package com.andye.warmod.silo.client;import com.andye.warmod.antiair.client.render.AntiAirMissileMesh;import com.andye.warmod.icbm.client.render.*;import com.andye.warmod.silo.SiloMissileType;import com.mojang.blaze3d.vertex.*;public final class MissileSiloMissileMesh{private MissileSiloMissileMesh(){}public static void render(PoseStack.Pose p,VertexConsumer b,SiloMissileType type,int light){if(type.role()==com.andye.warmod.silo.SiloMissileRole.INTERCEPTOR)AntiAirMissileMesh.render(p,b,type.antiAirVariant().orElseThrow(),light);else IcbmMissileMesh.render(p,b,IcbmPayloadAppearance.from(type.payloadType().orElseThrow()),IcbmLongRangeRenderContext.Lod.NEAR,light);}}